import { action, define, markRaw, model, observable } from '@formily/reactive';
import { FormStepEnv, IFormStep } from '../types';
import { Form } from '@formily/core';

export const createFormStep = (defaultCurrent = 0) => {
  const env: FormStepEnv = define(
    {
      form: undefined as unknown as Form,
      mode: undefined,
      steps: [],
    },
    {
      form: observable.ref,
      steps: observable.shallow,
      mode: observable.ref,
    }
  );

  const setDisplay = action.bound!((target: number) => {
    const currentStep = env.steps?.[target];
    env.steps?.forEach(({ name }) => {
      env.form?.query(name).take(field => {
        if (name === currentStep.name) {
          field.setDisplay('visible');
        } else {
          field.setDisplay('hidden');
        }
      });
    });
  });

  // @ts-ignore
  const formStep: IFormStep = model({
    connect: options => {
      env.steps = options.steps;
      env.form = options.form;
      env.beforeStepChange = options.beforeStepChange;
      env.onStepChange = options.onStepChange;
      if (!options.form) {
        console.error('FormStep connect need form instance, please use FormProvider to wrap the FormStep Component');
      }

      if (!options.steps) {
        console.warn(
          'No steps analyzed on the FormStep components, you can use StepPane Component or SchemaField to be the FormStep Component children'
        );
      }
      formStep.mode = options.mode || 'Schema';
    },
    current: defaultCurrent,
    mode: 'Schema',
    setCurrent(key: number) {
      setDisplay(key);
      formStep.current = key;
      env.onStepChange?.(key, formStep);
    },
    get allowNext() {
      return formStep.current < env.steps.length - 1;
    },
    get allowBack() {
      return formStep.current > 0;
    },
    get form() {
      return env.form;
    },
    nexting: false,
    setNexting(flag: boolean) {
      formStep.nexting = flag;
    },
    backing: false,
    setBacking(flag: boolean) {
      formStep.backing = flag;
    },
    async next() {
      if (formStep.allowNext) {
        try {
          formStep.setNexting(true);
          const target = formStep.current + 1;
          const canGoNext = (await env.beforeStepChange?.(formStep, target)) ?? true;
          canGoNext && (await env.form?.validate());
          if (canGoNext && env.form?.valid) {
            formStep.setCurrent(target);
          }
          formStep.setNexting(false);
        } catch (error) {
          formStep.setNexting(false);
          console.error('next', error);
        }
      }
    },
    async nextBySkipValidate() {
      if (formStep.allowNext) {
        try {
          const target = formStep.current + 1;
          const canGoNext = (await env.beforeStepChange?.(formStep, target)) ?? true;
          canGoNext && formStep.setCurrent(target);
        } catch (error) {
          console.error('nextBySkipValidate', error);
        }
      }
    },
    async back() {
      if (formStep.allowBack) {
        try {
          formStep.setBacking(true);
          const target = this.current - 1;
          const canGoBack = (await env.beforeStepChange?.(formStep, target)) ?? true;
          canGoBack && this.setCurrent(target);
          formStep.setBacking(false);
        } catch (error) {
          formStep.setBacking(false);
          console.error('back', error);
        }
      }
    },
    async submit(onSubmit) {
      try {
        await env.form?.submit?.(onSubmit);
      } catch (error) {
        console.error('表单校验错误', error);
      }
    },
  });

  return markRaw(formStep);
};
